// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue } from '@skyramp/skyramp';
import { postLink, getLinksList, deleteLinks } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Unorganized"
        },
        "description": "",
        "name": "tb-badcursor-a",
        "tags": [],
        "type": "url",
        "url": "https://example.com/tb-badcursor-a"
    }`;

    const linksPostResponse = await postLink(client, URL_localhost, headers, linksPostRequestBody, 200);
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getValue(linksPostResponse, "response.name"), 'name').toBe("tb-badcursor-a");
    expect(getValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/tb-badcursor-a");
    expect(getValue(linksPostResponse, "response.description"), 'description').toBe("");
    expect(getValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    const linkAId = getValue(linksPostResponse, "response.id");

    // Request Body
    const linksPost1RequestBody: string = `{
        "collection": {
            "name": "Unorganized"
        },
        "description": "",
        "name": "tb-badcursor-b",
        "tags": [],
        "type": "url",
        "url": "https://example.com/tb-badcursor-b"
    }`;

    const linksPost1Response = await postLink(client, URL_localhost, headers, linksPost1RequestBody, 200);
    expect(linksPost1Response.statusCode, 'status code').toBe(200);
    expect(getValue(linksPost1Response, "response.name"), 'name').toBe("tb-badcursor-b");
    expect(getValue(linksPost1Response, "response.url"), 'url').toBe("https://example.com/tb-badcursor-b");
    expect(getValue(linksPost1Response, "response.description"), 'description').toBe("");
    expect(getValue(linksPost1Response, "response.type"), 'type').toBe("url");
    expect(getValue(linksPost1Response, "response.id"), 'id').toBeGreaterThan(0);
    expect(getValue(linksPost1Response, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    const linkBId = getValue(linksPost1Response, "response.id");

    // Request Body
    const linksDeleteRequestBody: string = `{
        "linkIds": [
            ${linkAId},
            ${linkBId}
        ]
    }`;

    try {
        const linksGetResponse = await getLinksList(client, URL_localhost, headers, "0", 400, "notanumber");
        expect(linksGetResponse.statusCode, 'status code').toBe(400);
        expect(getValue(linksGetResponse, "response.0"), 'a rejected cursor returns no page of links').toBeNull();
    } finally {
        const linksDeleteResponse = await deleteLinks(client, URL_localhost, headers, linksDeleteRequestBody, 200);
        expect(linksDeleteResponse.statusCode, 'status code').toBe(200);
        expect(getValue(linksDeleteResponse, "response.count"), 'both links this test created were deleted').toBe(2);
    }
});
